require "timekeeping_relay"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe "Relay delivery to the fake projection endpoint" do
  it "resends the unsent rows to the fake projection after an outage and marks them sent only then" do
    source = Class.new do
      attr_reader :sent

      def initialize(rows)
        @rows = rows
        @sent = []
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }.first(limit)
      end

      def mark_sent(positions)
        @sent |= positions
        nil
      end
    end.new([
      { "generation" => 1, "outbox_position" => 1, "entry" => { "id" => 10, "company_id" => 1, "version" => 1 } },
      { "generation" => 1, "outbox_position" => 2, "entry" => { "id" => 11, "company_id" => 1, "version" => 1 } }
    ])
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    fake = TimekeepingContract::FakeRelay.new(source: timekeeping)
    endpoint = Class.new do
      attr_accessor :down
      attr_reader :posts

      def initialize(fake, credential)
        @fake = fake
        @credential = credential
        @posts = 0
      end

      def deliver(batch, idempotency_key:)
        @posts += 1
        return TimekeepingRelay::Response.new(status: 503, body: {}) if down

        answer = @fake.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                            headers: { "Authorization" => "Bearer #{@credential}", "Idempotency-Key" => idempotency_key },
                            body: batch)
        TimekeepingRelay::Response.new(status: answer.status, body: answer.body)
      end
    end.new(fake, credential)
    relay = TimekeepingRelay::Relay.new(source:, endpoint:)

    endpoint.down = true
    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    expect(relay.deliver(limit: 10)).to eq(sent: 0, last_position: nil)
    expect(source.sent).to eq([])
    expect(fake.projected_entry(10)).to be_nil

    endpoint.down = false
    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 2)
    expect(source.sent).to contain_exactly(1, 2)
    expect(fake.projected_entry(10)).to include("id" => 10, "version" => 1)
    expect(fake.projected_entry(11)).to include("id" => 11, "version" => 1)
  end
end

require "timekeeping_relay"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe "Relay delivery to the fake projection endpoint" do
  it "counts an already applied row as ignored when it is resent inside a larger batch after a lost mark" do
    source = Class.new do
      attr_reader :sent, :rows
      attr_accessor :failing_marks

      def initialize(rows)
        @rows = rows
        @sent = []
        @failing_marks = 0
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }.first(limit)
      end

      def mark_sent(positions)
        if failing_marks.positive?
          self.failing_marks -= 1
          raise "outbox write failed"
        end
        @sent |= positions
        nil
      end
    end.new([{ "generation" => 1, "outbox_position" => 1, "entry" => { "id" => 10, "company_id" => 1, "version" => 1 } }])
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    fake = TimekeepingContract::FakeRelay.new(source: timekeeping)
    endpoint = Class.new do
      attr_reader :answers

      def initialize(fake, credential)
        @fake = fake
        @credential = credential
        @answers = []
      end

      def deliver(batch, idempotency_key:)
        answer = @fake.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                            headers: { "Authorization" => "Bearer #{@credential}", "Idempotency-Key" => idempotency_key },
                            body: batch)
        @answers << answer
        TimekeepingRelay::Response.new(status: answer.status, body: answer.body)
      end
    end.new(fake, credential)
    relay = TimekeepingRelay::Relay.new(source:, endpoint:)

    source.failing_marks = 1
    begin
      relay.deliver(limit: 10)
    rescue RuntimeError
      nil
    end
    expect(source.sent).to eq([])

    # A newer row arrives, so the resend is a different batch with a new key.
    source.rows << { "generation" => 1, "outbox_position" => 2, "entry" => { "id" => 11, "company_id" => 1, "version" => 1 } }
    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 2)

    expect(endpoint.answers.last.status).to eq(200)
    expect(endpoint.answers.last.body).to eq("applied" => 1, "ignored" => 1)
    expect(source.sent).to contain_exactly(1, 2)
    expect(fake.projected_entry(10)).to include("id" => 10, "version" => 1)
    expect(fake.projected_entry(11)).to include("id" => 11, "version" => 1)
  end
end

